    font-size: 1.1rem;
    color: #f2f3f5;
}

.channel-desc {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
