    display: flex;
    gap: 4px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 6px 8px;
    margin-top: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

.emoji-option {
    font-size: 1.2rem;
    cursor: pointer;
    padding: 2px 4px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-option:hover {
    background: #3f4147;
}

