    color: #dbdee1;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #1e1f22;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #f2f3f5;
}

.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #3f4147;
    color: #f2f3f5;
}

.thread-root-message {
    padding: 12px 16px;
    background: #232428;
    border-bottom: 1px solid #3f4147;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    color: #949ba4;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.thread-reply {
    padding: 6px 0;
}

.thread-reply .message-content {
    font-size: 0.85rem;
}
