+    border-bottom: 1px solid #3f4147;
+    flex-shrink: 0;
+}
+
+.message-area-header h2 {
+    margin: 0;
+    font-size: 1.1rem;
+    color: #f2f3f5;
+}
+
+.channel-desc {
+    margin: 4px 0 0;
+    font-size: 0.8rem;
+    color: #949ba4;
+}
+
+.message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 16px 20px;
+    display: flex;
+    flex-direction: column;
+    gap: 4px;
+}
+
+.loading-indicator {
+    text-align: center;
+    padding: 8px;
+    color: #949ba4;
+    font-size: 0.85rem;
+}
+
+.no-channel-selected {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    flex: 1;
+    color: #949ba4;
+}
+
+/* Message Bubble */
+.message-bubble {
+    padding: 8px 12px;
+    border-radius: 6px;
+    position: relative;
+    transition: background 0.1s;
+}
+
+.message-bubble:hover {
+    background: #2e3035;
+}
+
+.message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+}
+
+.message-author {
+    font-weight: 600;
+    color: #f2f3f5;
+    font-size: 0.9rem;
+}
+
+.message-time {
+    font-size: 0.72rem;
+    color: #949ba4;
+}
+
+.message-content {
+    margin-top: 4px;
+    font-size: 0.9rem;
+    line-height: 1.4;
+    word-break: break-word;
+}
+
+.reaction-row {
+    display: flex;
+    gap: 4px;
+    margin-top: 6px;
+    flex-wrap: wrap;
+}
+
+.reaction-badge {
+    background: #3f4147;
+    border: 1px solid #4e5058;
+    border-radius: 4px;
+    padding: 2px 6px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    transition: background 0.1s;
+}
+
+.reaction-badge:hover {
+    background: #4e5058;
+}
+
+.thread-link {
+    font-size: 0.8rem;
+    color: #00a8fc;
+    cursor: pointer;
+    margin-top: 4px;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+.message-actions {
+    position: absolute;
+    top: -8px;
+    right: 8px;
+    display: flex;
+    gap: 4px;
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 4px;
+    padding: 2px 4px;
+    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
+}
+
+.action-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 0.75rem;
+    cursor: pointer;
+    padding: 4px 6px;
+    border-radius: 3px;
+}
+
+.action-btn:hover {
+    background: #3f4147;
+    color: #f2f3f5;
+}
+
+.emoji-picker {
+    display: flex;
+    gap: 4px;
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 6px;
+    padding: 6px 8px;
+    margin-top: 4px;
+    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
+}
+
+.emoji-option {
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 2px 4px;
+    border-radius: 4px;
+    transition: background 0.1s;
+}
+
+.emoji-option:hover {
+    background: #3f4147;
+}
+
+/* Message Input */
+.message-input-area {
+    padding: 12px 20px;
+    border-top: 1px solid #3f4147;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+    flex-shrink: 0;
+}
+
+.message-textarea {
+    flex: 1;
+    resize: none;
+    background: #383a40;
+    border: 1px solid #4e5058;
+    border-radius: 8px;
+    color: #dbdee1;
+    padding: 10px 14px;
+    font-size: 0.9rem;
+    font-family: inherit;
+    outline: none;
+    transition: border-color 0.15s;
+}
+
+.message-textarea:focus {
+    border-color: #5865f2;
+}
+
+.message-textarea::placeholder {
+    color: #6d6f78;
+}
+
+.send-btn {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 10px 18px;
+    font-weight: 600;
+    font-size: 0.85rem;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+.send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+.send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2b2d31;
+    color: #dbdee1;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #1e1f22;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #3f4147;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #f2f3f5;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #3f4147;
+    color: #f2f3f5;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    background: #232428;
+    border-bottom: 1px solid #3f4147;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    font-size: 0.85rem;
+    color: #949ba4;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+.thread-reply {
+    padding: 6px 0;
+}
+
+.thread-reply .message-content {
+    font-size: 0.85rem;
+}
+

